typedef void (*EventCallback)(int event_id, void* payload);

// Static storage for the registered handler
static EventCallback current_handler = NULL;

// Function to register the callback
void register_event_handler(EventCallback handler) {
    current_handler = handler;
}

// Example user function conforming to the signature
void log_action(int id, void* data) {
    // Runtime logic here
}

// Function that triggers the event
void system_trigger(int event_id, void* data) {
    if (current_handler != NULL) {
        // Callback invocation (the core event loop action)
        current_handler(event_id, data);
    }
}

